        uint balBefore = c.balances(address(this));
        uint cBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;

        bool reverted;
        if (cashOutAmt <= balBefore) {
            try c.CashOut(cashOutAmt) {
                reverted = false;
