        } else {
            try c.CashOut(cashOutAmt) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted && c.balances(address(this)) == balBefore && address(c).balance == cBalBefore && address(this).balance == selfBalBefore);
        }
    }

    receive() external payable {}
}

